import lzString from "lz-string";

export function generateUUID() {
  var d = new Date().getTime(); //Timestamp
  var d2 =
    (typeof performance !== "undefined" &&
      performance.now &&
      performance.now() * 1000) ||
    0; //Time in microseconds since page-load or 0 if unsupported
  return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, function (c) {
    var r = Math.random() * 16; //random number between 0 and 16
    if (d > 0) {
      //Use timestamp until depleted
      r = (d + r) % 16 | 0;
      d = Math.floor(d / 16);
    } else {
      //Use microseconds since page-load if supported
      r = (d2 + r) % 16 | 0;
      d2 = Math.floor(d2 / 16);
    }
    return (c === "x" ? r : (r & 0x3) | 0x8).toString(16);
  });
}

export const compressLZW = (data) => {
  if (typeof data === "object") {
    return lzString.compressToEncodedURIComponent(JSON.stringify(data));
  }

  return lzString.compressToEncodedURIComponent(data);
};

export const compressBase64 = (data) => {
  if (typeof data === "object") {
    return lzString.compressToBase64(JSON.stringify(data));
  }

  return lzString.compressToBase64(data);
};

export const decompressBase64 = (data) => {
  if (typeof data === "object") {
    return lzString.decompressFromBase64(JSON.stringify(data));
  }

  return lzString.decompressFromBase64(data);
};

/**
 * Decompress strin
 * @param {string} compressed - Compressed string to decompress
 * @returns {string} decompressed string
 */
export const decompressLZW = (compressed) =>
  lzString.decompressFromEncodedURIComponent(compressed);

/**
 * Decompress data
 * @param {string} compressed - Compressed data to decompress
 * @returns {object} decompressed data as an object
 */
export const parseDecompressLZW = (compressed) =>
  JSON.parse(decompressLZW(compressed));


export const getPostData = (tag, frmData, adTag, adData) => {

  var frmHdr = {};
  frmHdr["convid"] = generateUUID();
  frmHdr["tag"] = tag;
  frmHdr["orgid"] = ""
  frmHdr["vendid"] = "0"

  var data = {};
  data["hdr"] = frmHdr;
  data["body"] = frmData;
  if (adData) {
    data[adTag] = adData;
  }

  return data;
}